/*
 * prog59_rule110 – original behaviour of the supplied binary
 *
 * The program expects two command‑line arguments:
 *   1. A binary string (only characters ‘0’ and ‘1’) – the initial row.
 *   2. A decimal integer – the number of generations to display.
 *
 * Constraints (exactly as the original binary enforces):
 *   • The binary string must be non‑empty and at most 60 characters long.
 *   • The integer must be a valid decimal number (no extra characters) and
 *     non‑negative.  If it is larger than 200 it is silently capped to 200.
 *
 * If any of the above checks fail the program prints the single line
 *   INVALID_INPUT
 * (followed by a newline) and exits with status 1.
 *
 * Otherwise the program prints the initial row and then the next
 * (steps‑1) rows generated by elementary cellular automaton Rule 110.
 * Each row is printed on its own line and the output is terminated by a
 * final newline.
 *
 * Rule 110 (binary 01101110) maps the three‑cell neighbourhood
 * (left, centre, right) to a new cell value as follows:
 *
 *   111 → 0   110 → 1   101 → 1   100 → 0
 *   011 → 1   010 → 1   001 → 1   000 → 0
 *
 * The implementation treats cells outside the supplied string as 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WIDTH 60
#define MAX_STEPS 200

/* Rule 110 lookup table: index = (left<<2)|(center<<1)|right */
static const char RULE110[8] = {
    '0', /* 000 */
    '1', /* 001 */
    '1', /* 010 */
    '1', /* 011 */
    '0', /* 100 */
    '1', /* 101 */
    '1', /* 110 */
    '0'  /* 111 */
};

/* Print the error message used by the original binary and exit. */
static void invalid_input(void) {
    puts("INVALID_INPUT");
    exit(1);
}

/* Verify that a string consists only of ‘0’ and ‘1’. */
static int is_binary_string(const char *s) {
    while (*s) {
        if (*s != '0' && *s != '1')
            return 0;
        ++s;
    }
    return 1;
}

/* Compute the next generation of a binary row using Rule 110. */
static void next_row(const char *cur, char *next, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        char left   = (i == 0)     ? '0' : cur[i - 1];
        char centre = cur[i];
        char right  = (i + 1 == len) ? '0' : cur[i + 1];

        int idx = ((left   - '0') << 2) |
                  ((centre - '0') << 1) |
                  (right  - '0');

        next[i] = RULE110[idx];
    }
    next[len] = '\0';
}

int main(int argc, char *argv[]) {
    /* ----- argument count check ----- */
    if (argc < 3) {
        invalid_input();               /* too few arguments */
    }

    /* ----- first argument: initial row ----- */
    const char *init = argv[1];
    size_t width = strlen(init);

    if (width == 0 || width > MAX_WIDTH) {
        invalid_input();               /* empty or too long */
    }
    if (!is_binary_string(init)) {
        invalid_input();               /* contains characters other than 0/1 */
    }

    /* ----- second argument: number of steps ----- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {
        invalid_input();               /* not a pure decimal number */
    }
    if (steps < 0) {
        invalid_input();               /* negative step count */
    }
    if (steps > MAX_STEPS) {
        steps = MAX_STEPS;             /* cap to 200 as the original binary does */
    }

    /* ----- simulation ----- */
    char cur[MAX_WIDTH + 1];
    char nxt[MAX_WIDTH + 1];

    memcpy(cur, init, width);
    cur[width] = '\0';

    for (long gen = 0; gen < steps; ++gen) {
        puts(cur);                     /* print current generation */
        next_row(cur, nxt, width);     /* compute next generation */
        memcpy(cur, nxt, width + 1);   /* prepare for next loop */
    }

    return 0;
}
